import { id } from 'ethers';
import { canonical } from './files.mjs';

export const HARDWARE_MAX_AGE_MS = 360_000;

// The Arduino firmware publishes INA219 telemetry, without an AI prediction.
// Estimate the next interval from the last measured net energy; never label it AI.
// accelerated: one logical 5-minute sample per 5 wall-clock seconds. simulated:
// generated by the board's demo mode instead of measured by its INA219 sensors.
export function hardwareSource(reading, home, now = Date.now(), accelerated = false, simulated = accelerated) {
  const measured = reading?.data_mode === 'real' && reading.demo_scenario === 'none';
  const modeValid = accelerated
    ? reading?.time_mode === 'accelerated' && reading.sampling_seconds === 5 &&
      (simulated ? reading.data_mode === 'simulation' && ['sell', 'buy', 'hold'].includes(reading.demo_scenario) : measured)
    : measured && reading.time_mode === undefined;
  if (!reading || reading.schema_version !== 1 || reading.household_id !== 'home_01' ||
      !/^[a-f0-9]{32}$/.test(reading.run_id || '') ||
      !new RegExp(`^${reading.run_id}:home_01:(0|[1-9][0-9]*)$`).test(reading.event_id || '') ||
      reading.interval_seconds !== 300 || !modeValid ||
      !/^\d{4}-\d{2}-\d{2}T\d{2}:(00|05|10|15|20|25|30|35|40|45|50|55):00\+07:00$/.test(reading.timestamp || ''))
    throw new Error(!accelerated ? 'Cần telemetry INA219 thật, đúng Nhà 1 và khoảng 5 phút'
      : simulated ? 'Cần telemetry mô phỏng 5s mới của ESP32; nạp firmware esp32_edge và bật demo on'
        : 'Cần số đo INA219 thật nhịp 5s của ESP32; nạp firmware esp32_edge, dùng demo off và real fast');
  const age = now - Date.parse(reading.received_at);
  if (!Number.isFinite(age) || age < -5000 || age > (accelerated ? 20000 : HARDWARE_MAX_AGE_MS))
    throw new Error(`Số đo ESP32 đã cũ; chờ bản tin ${accelerated ? '5 giây' : '5 phút'} mới`);
  const sampleAge = now - Date.parse(reading.timestamp);
  if (!Number.isFinite(sampleAge) || (!accelerated && (sampleAge < 0 || sampleAge > 660_000)))
    throw new Error('Thời gian số đo ESP32 không khớp đồng hồ hiện tại');
  for (const k of ['solar_power_kw', 'load_power_kw', 'solar_energy_kwh', 'load_energy_kwh',
    'solar_voltage_v', 'solar_current_a', 'load_voltage_v', 'load_current_a'])
    if (typeof reading[k] !== 'number' || !Number.isFinite(reading[k]) || reading[k] < 0)
      throw new Error(`Số đo ESP32 không hợp lệ: ${k}`);
  if (Math.max(reading.solar_power_kw, reading.load_power_kw) > 1000 ||
      Math.abs(reading.solar_energy_kwh - reading.solar_power_kw / 12) > .00001 ||
      Math.abs(reading.load_energy_kwh - reading.load_power_kw / 12) > .00001)
    throw new Error('Công suất và điện năng ESP32 không nhất quán');
  const energy = reading.solar_energy_kwh - reading.load_energy_kwh;
  const quantityWh = Math.floor(Math.abs(energy) * 1000 + 1e-9);
  const action = quantityWh === 0 ? 'hold' : energy > 0 ? 'sell' : 'buy';
  const target = new Date(Date.parse(reading.timestamp) + 300_000 + 7 * 3600_000).toISOString().slice(0, 19) + '+07:00';
  const { received_at, ...input } = reading;
  const data = { schema_version: 1, basis: 'esp32_telemetry', policy_version: 'measured-net-next5m-v1',
    input, received_at, action, quantity_wh: String(quantityWh),
    price: String(action === 'sell' ? home.ask : home.bid), target_timestamp: target };
  return { ...data, device_kind: 'esp32', input_event_id: reading.event_id,
    source_id: id(`esp32-measured-v1:${reading.event_id}`), data_hash: id(canonical(data)) };
}

export function validateHardwareForecast(forecast, config, now = Date.now()) {
  const ai = config.hybrid_source !== 'telemetry';
  if (!config.hybrid || forecast?.household_id !== 'home_01' || forecast.basis !== (ai ? 'esp32_forecast' : 'esp32_telemetry'))
    throw new Error('Nguồn ESP32 chỉ được dùng trong bản 1 ESP32 + 11 hộ mô phỏng');
  const reading = { ...forecast.input, received_at: forecast.received_at };
  const expected = ai ? edgeAiSource(reading, forecast.ai_prediction, config.homes[0], now, config.ai_model_version,
    ['ai-demo', 'ai-live'].includes(config.hybrid_source), config.hybrid_source === 'ai-demo')
    : hardwareSource(reading, config.homes[0], now);
  for (const key of Object.keys(expected))
    if (canonical(expected[key]) !== canonical(forecast[key])) throw new Error(`Nguồn ESP32 bị thay đổi: ${key}`);
  return forecast;
}

export function edgeAiSource(reading, prediction, home, now = Date.now(), expectedModel, accelerated = false, simulated = accelerated) {
  const measured = hardwareSource(reading, home, now, accelerated, simulated);
  const p = prediction;
  if (!p || p.schema_version !== 1 || p.household_id !== 'home_01' || p.device_kind !== 'esp32' ||
      !/^esp32-[a-f0-9]{12}$/.test(p.device_id || '') || p.run_id !== reading.run_id ||
      p.input_event_id !== reading.event_id || p.input_timestamp !== reading.timestamp || p.interval_seconds !== 300 ||
      p.target_timestamp !== measured.target_timestamp || p.data_mode !== (simulated ? 'simulation' : 'real') || p.history_samples !== 12 ||
      (accelerated ? p.time_mode !== 'accelerated' || p.sampling_seconds !== 5 : p.time_mode === 'accelerated') ||
      !expectedModel || p.model_version !== expectedModel || p.late === true)
    throw new Error(`Cần dự báo Edge AI ${!accelerated ? 'thật' : simulated ? 'mô phỏng 5s' : 'từ cảm biến thật 5s'}, đúng model và đúng đầu vào Nhà 1; chờ đủ 12 mẫu liên tiếp (~${accelerated ? '60 giây' : '60 phút'})`);
  const age = now - Date.parse(p.received_at);
  if (!Number.isFinite(age) || age < -5000 || age > (accelerated ? 20000 : HARDWARE_MAX_AGE_MS) || (!accelerated && now >= Date.parse(p.target_timestamp) + 300000))
    throw new Error('Dự báo Edge AI đã cũ hoặc hết khoảng đích; chờ dự báo mới');
  for (const key of ['predicted_solar_kw', 'predicted_load_kw', 'predicted_net_kw', 'predicted_surplus_kwh'])
    if (typeof p[key] !== 'number' || !Number.isFinite(p[key]) || (key !== 'predicted_net_kw' && p[key] < 0))
      throw new Error(`Dự báo AI không hợp lệ: ${key}`);
  const net = p.predicted_solar_kw - p.predicted_load_kw;
  if (Math.max(p.predicted_solar_kw, p.predicted_load_kw) > 1000 || Math.abs(net - p.predicted_net_kw) > .00001 ||
      Math.abs(Math.max(0, net) / 12 - p.predicted_surplus_kwh) > .00001)
    throw new Error('Công suất và điện năng dự báo AI không nhất quán');
  for (const key of ['inference_us', 'arena_used_bytes', 'free_heap_bytes', 'clipped_features', 'model_bytes'])
    if (!Number.isSafeInteger(p[key]) || p[key] < 0) throw new Error(`Thiếu chẩn đoán Edge AI: ${key}`);
  const q = Math.floor(Math.abs(net) * 1000 / 12 + 1e-9);
  const action = q === 0 ? 'hold' : net > 0 ? 'sell' : 'buy';
  const data = { schema_version: 1, basis: 'esp32_forecast', policy_version: !accelerated ? 'edge-ai-next5m-v1' : simulated ? 'edge-ai-accelerated5s-v1' : 'edge-ai-live5s-v1',
    input: measured.input, received_at: reading.received_at, ai_prediction: p, action, quantity_wh: String(q),
    price: String(action === 'sell' ? home.ask : home.bid), target_timestamp: p.target_timestamp };
  return { ...data, device_kind: 'esp32', input_event_id: reading.event_id,
    source_id: id(`esp32-ai-v1:${p.device_id}:${p.input_event_id}`), data_hash: id(canonical(data)) };
}
